/**
 * Seeds users + a replayable history. Usage: npm run seed [-- --minutes 15]
 * History is generated by the same deterministic simulator, so it contains the legit load change AND the scheduled
 * cobble(s); detection is run over the whole history exactly like live ingestion would.
 */
import './env';
import bcrypt from 'bcryptjs';
import { ensureSchema, pool, q } from '../lib/db';
import { generate } from '../lib/simulator';
import { insertReadings, rollup, detectRange } from '../lib/engine';
import { MILLS } from '../lib/signals';

const arg = (n: string, d: number) => { const i = process.argv.indexOf('--' + n); return i > 0 ? Number(process.argv[i + 1]) : d; };

(async () => {
  await ensureSchema();
  const email = 'demo@monoedge.dev', pw = 'Demo@12345';
  await q(`INSERT INTO users(email,password_hash) VALUES($1,$2) ON CONFLICT (email) DO NOTHING`, [email, await bcrypt.hash(pw, 10)]);
  const minutes = arg('minutes', 15);
  const end = Math.floor((Date.now() - 2000) / 20) * 20, start = end - minutes * 60_000;
  await pool.query('TRUNCATE readings, rollup_1s, alerts, sim_state, scenario_events');
  for (const mill of MILLS) {
    const t0 = Date.now();
    for (let a = start; a < end; a += 60_000) { // one minute at a time keeps memory flat
      const b = Math.min(a + 60_000, end);
      await insertReadings(generate(mill, a, b));
      await rollup(mill, a, b);
      await detectRange(mill, a, b);
    }
    await q('INSERT INTO sim_state(mill_id,cursor_ts) VALUES($1,$2) ON CONFLICT (mill_id) DO UPDATE SET cursor_ts=EXCLUDED.cursor_ts', [mill, new Date(end)]);
    console.log(`${mill}: ${minutes} min seeded in ${((Date.now() - t0) / 1000).toFixed(1)} s`);
  }
  const [{ n }] = await q('SELECT count(*)::int n FROM readings'); const al = await q('SELECT id,mill_id,kind,start_ts FROM alerts ORDER BY start_ts');
  console.log(`readings: ${n}\nalerts:`, al.map((a: any) => `#${a.id} ${a.mill_id} ${a.kind} @ ${a.start_ts.toISOString()}`));
  console.log(`demo login: ${email} / ${pw}`);
  await pool.end();
})();
